PAGE = dict(
    slug='z_tick_format',
    title='Pane::z_tick_format',
    signature='Pane& Pane::z_tick_format(TickFormat format) noexcept',
    intro='Chooses how the numbers on the z axis ticks are written. The format is stored in `z_axis().tick_format`; `TickFormat::Auto` (the default) picks plain or scientific notation from the size of the numbers, and the other formats force one style:\n\n| Format | Ticks are written as |\n|---|---|\n| `Auto` | chooses plain or scientific notation from the size of the numbers. |\n| `Plain` | plain decimal numbers with no trailing zeros. |\n| `Fixed3` | three decimals. |\n| `Fixed6` | six decimals. |\n| `Scientific` | scientific notation, `2.00e+06`. |\n| `Engineering` | engineering notation, exponents that are multiples of three. |\n| `Integer` | rounded to whole numbers. |\n| `Percent` | the value times 100 with a percent sign. |\n\nThe format shapes the automatic tick labels. Labels given explicitly with [`z_ticks`](z_ticks.md) or [`z_categories`](z_categories.md) are text, and are drawn as they were written. The number of decimals of the automatic labels in `Auto` is set with [`z_auto_tick_decimals`](z_auto_tick_decimals.md). The call never throws, and is read when the figure is rendered.',
    parameters='**format** (`TickFormat`)\n    One of the eight formats; see [`TickFormat`](../types/TickFormat.md).',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='The default is `Auto` (0); each call is read back, and the last call wins.',
             code='auto fig = studio("z_format_readback");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\nstd::cout << "new axis: " << static_cast<int>(pane.z_axis().tick_format) << " (Auto = 0)\\n";\npane.z_tick_format(TickFormat::Percent);\nstd::cout << "after Percent: " << static_cast<int>(pane.z_axis().tick_format) << "\\n";\npane.z_tick_format(TickFormat::Auto);\nstd::cout << "back to Auto: " << static_cast<int>(pane.z_axis().tick_format) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='small', text='Every format on the same small values. The axis runs 0 to 1, and each format writes the ticks in its own way; `Percent` multiplies by 100.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nconst std::pair<const char*, TickFormat> formats[] = {{"Auto", TickFormat::Auto}, {"Plain", TickFormat::Plain}, {"Fixed3", TickFormat::Fixed3}, {"Fixed6", TickFormat::Fixed6},\n                                                    {"Scientific", TickFormat::Scientific}, {"Engineering", TickFormat::Engineering}, {"Integer", TickFormat::Integer}, {"Percent", TickFormat::Percent}};\nfor (const auto& [name, format] : formats) {\nauto fig = studio("z_format_small");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\n  pane.x_tick_labels(false);\npane.y_tick_labels(false);\n  pane.z_tick_format(format);\n  std::cout << name << ": " << texts(fig.to_svg()) << "\\n";\n}\nauto fig = studio("z_format_small_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\npane.z_tick_format(TickFormat::Percent);\nfig.save_svg("figure.svg");'),
        dict(id='large', text='Every format on large values. The axis runs to about ten million; `Plain` and `Fixed3` write every digit, `Scientific` and `Engineering` keep the labels short, and `Auto` switches to scientific notation by itself.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nconst std::pair<const char*, TickFormat> formats[] = {{"Auto", TickFormat::Auto}, {"Plain", TickFormat::Plain}, {"Fixed3", TickFormat::Fixed3}, {"Scientific", TickFormat::Scientific}, {"Engineering", TickFormat::Engineering}, {"Integer", TickFormat::Integer}};\nfor (const auto& [name, format] : formats) {\nauto fig = studio("z_format_large");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{0, 1, 0, 1, 0}, std::vector<double>{1200, 34000, 560000, 7800000, 9000000});\n  pane.x_tick_labels(false);\npane.y_tick_labels(false);\n  pane.z_tick_format(format);\n  std::cout << name << ": " << texts(fig.to_svg()) << "\\n";\n}\nauto fig = studio("z_format_large_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{0, 1, 0, 1, 0}, std::vector<double>{1200, 34000, 560000, 7800000, 9000000});\npane.z_tick_format(TickFormat::Scientific);\nfig.save_svg("figure.svg");'),
        dict(id='distinct', text='Eight formats, eight figures. The formats that look alike on some data differ on others; here all pairs of neighbouring formats on the small values give different figures, and setting the same format twice changes nothing.',
             code='auto build = [&](TickFormat format) {\n  auto fig = studio("z_format_distinct");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\n  pane.z_tick_format(format);\n  return fig.to_svg();\n};\nstd::cout << "Plain vs Fixed3: " << (build(TickFormat::Plain) != build(TickFormat::Fixed3)) << ", Fixed3 vs Fixed6: " << (build(TickFormat::Fixed3) != build(TickFormat::Fixed6)) << ", Scientific vs Engineering: " << (build(TickFormat::Scientific) != build(TickFormat::Engineering)) << "\\n";\nstd::cout << "same format twice: " << (build(TickFormat::Percent) == build(TickFormat::Percent)) << "\\n";\nauto fig = studio("z_format_distinct_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\nfig.save_svg("figure.svg");'),
        dict(id='explicit_ticks', text='Explicit tick labels keep their text. Labels given with `z_ticks` are drawn as written, whatever the format; the format applies to the automatic ticks.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto fig = studio("z_format_explicit");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{1, 2, 3, 4});\npane.x_tick_labels(false);\npane.y_tick_labels(false);\npane.z_ticks(std::vector<double>{1, 2, 3}, {"low", "mid", "high"});\npane.z_tick_format(TickFormat::Percent);\nstd::cout << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- `noexcept`. A format changes only how ticks are written, never where they are.\n- The format is per axis: set it on each axis that should use it.',
    see=['[`Pane::z_auto_tick_decimals`](z_auto_tick_decimals.md): decimals of the automatic labels.', '[`Pane::z_ticks`](z_ticks.md): explicit tick labels.', '[`TickFormat`](../types/TickFormat.md): the values.', '[`Pane::x_tick_format`](x_tick_format.md): the same setting for the x axis.', '[`Pane::y_tick_format`](y_tick_format.md): the same setting for the y axis.'],
)
